import SwiftUI
import KanbanCore

/// Named colours from Palette.xcassets (generated by scripts/generate_palette.py),
/// each with light and dark variants. Shared by the app and the widget.
/// Priority is the only colour on the board (DESIGN.md v2).
enum Palette {
    static var background: Color { named("Background") }
    static var widgetBackground: Color { named("WidgetBackground") }
    static var hairline: Color { named("Hairline") }
    static var textPrimary: Color { named("TextPrimary") }
    static var textSecondary: Color { named("TextSecondary") }
    static var textTertiary: Color { named("TextTertiary") }
    static var field: Color { named("Field") }
    static var buttonPrimary: Color { named("ButtonPrimary") }
    static var buttonPrimaryText: Color { named("ButtonPrimaryText") }
    static var wipWarning: Color { named("WIPWarning") }
    static var overdue: Color { named("Overdue") }
    static var appAccent: Color { named("AccentColor") }

    /// Panel colours for a priority. Done panels use `.none`.
    static func fill(_ priority: Priority) -> Color { named("\(priority.assetName)Fill") }
    static func border(_ priority: Priority) -> Color { named("\(priority.assetName)Border") }
    static func ink(_ priority: Priority) -> Color { named("\(priority.assetName)Ink") }
    static func separator(_ priority: Priority) -> Color { named("\(priority.assetName)Separator") }
    #if os(iOS)
    /// The vivid system colour for a priority (iPhone palette only): dots and swipe buttons.
    static func accent(_ priority: Priority) -> Color { named("\(priority.assetName)Accent") }
    #endif

    private static func named(_ name: String) -> Color { Color(name) }
}

extension Priority {
    var assetName: String {
        switch self {
        case .high: "High"
        case .medium: "Medium"
        case .low: "Low"
        case .none: "None"
        }
    }

    /// The widget's one-letter priority mark.
    var letter: String {
        switch self {
        case .high: "H"
        case .medium: "M"
        case .low: "L"
        case .none: ""
        }
    }
}

extension Font {
    /// New York, for the window and column titles.
    static func serif(_ size: CGFloat, weight: Font.Weight = .regular) -> Font {
        .system(size: size, weight: weight, design: .serif)
    }
}
